def load_factor(buckets):
    count = 0
    for bucket in buckets:
        count += len(bucket)
    return count / len(buckets)

print(load_factor([[], []]))
print(load_factor([[(0, "A"), (2, "B")], []]))
print(load_factor([[(0, 1), (4, 1)], [(1, 1), (5, 1)], [(2, 1)], [(3, 1)]]))

def rehash_copy(buckets, new_count):
    result = []
    for _ in range(new_count):
        result.append([])
    for bucket in buckets:
        for key, value in bucket:
            result[key % new_count].append((key, value))
    return result

print(rehash_copy([[], [(1, "A"), (3, "B")]], 4))
print(rehash_copy([[], []], 1))
print(rehash_copy([[(0, None)]], 2))

def crowded_buckets(buckets, limit):
    result = []
    for index, bucket in enumerate(buckets):
        if len(bucket) > limit:
            result.append(index)
    return result

print(crowded_buckets([[], []], 0))
print(crowded_buckets([[(0, "A"), (3, "B")], [(1, "C")], []], 1))
print(crowded_buckets([[(0, "A")], [(1, "B")], [(2, "C")]], 1))
